import { describe, it, expect, beforeEach, vi, afterEach } from "vitest";
import request from "supertest";
import { app } from "../src/server.js";

describe("Rate Limiter Middleware", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("allows requests within the limit", async () => {
    const res1 = await request(app).get("/");
    expect(res1.status).toBe(200);
    expect(res1.get("X-RateLimit-Limit")).toBe("60");
    expect(res1.get("X-RateLimit-Remaining")).toBe("59");
  });

  it("sets rate limit headers on every request", async () => {
    const res = await request(app).get("/");
    expect(res.get("X-RateLimit-Limit")).toBe("60");
    expect(res.get("X-RateLimit-Remaining")).toBeDefined();
    expect(res.get("X-RateLimit-Reset")).toBeDefined();
  });

  it("decrements remaining count with each request", async () => {
    const res1 = await request(app).get("/");
    const remaining1 = parseInt(res1.get("X-RateLimit-Remaining") || "0");

    const res2 = await request(app).get("/");
    const remaining2 = parseInt(res2.get("X-RateLimit-Remaining") || "0");

    expect(remaining2).toBe(remaining1 - 1);
  });

  it("returns 429 when limit is exceeded", async () => {
    // Use up all 60 tokens
    for (let i = 0; i < 60; i++) {
      const res = await request(app).get("/");
      expect(res.status).toBe(200);
    }

    // Next request should be rate limited
    const res = await request(app).get("/");
    expect(res.status).toBe(429);
    expect(res.body.error).toBe("Rate limit exceeded");
    expect(res.body.retryAfter).toBeDefined();
  });

  it("returns Retry-After header when rate limited", async () => {
    // Use up all 60 tokens
    for (let i = 0; i < 60; i++) {
      await request(app).get("/");
    }

    const res = await request(app).get("/");
    expect(res.status).toBe(429);
    expect(res.get("Retry-After")).toBeDefined();
    const retryAfter = parseInt(res.get("Retry-After") || "0");
    expect(retryAfter).toBeGreaterThan(0);
    expect(retryAfter).toBeLessThanOrEqual(60);
  });

  it("resets the window after 60 seconds", async () => {
    // Use up all 60 tokens
    for (let i = 0; i < 60; i++) {
      await request(app).get("/");
    }

    // Verify rate limited
    let res = await request(app).get("/");
    expect(res.status).toBe(429);

    // Advance time by 60 seconds
    vi.advanceTimersByTime(60000);

    // Should be allowed again
    res = await request(app).get("/");
    expect(res.status).toBe(200);
    expect(res.get("X-RateLimit-Remaining")).toBe("59");
  });

  it("allows partial refill based on elapsed time", async () => {
    // Use up all 60 tokens
    for (let i = 0; i < 60; i++) {
      await request(app).get("/");
    }

    // Verify rate limited
    let res = await request(app).get("/");
    expect(res.status).toBe(429);

    // Advance time by 30 seconds (half the refill interval)
    vi.advanceTimersByTime(30000);

    // Should have ~30 tokens refilled, allowing one request
    res = await request(app).get("/");
    expect(res.status).toBe(200);
  });

  it("caps tokens at the maximum", async () => {
    const res = await request(app).get("/");
    const remaining = parseInt(res.get("X-RateLimit-Remaining") || "0");
    expect(remaining).toBeLessThanOrEqual(60);
  });
});

