import type { Request, Response, NextFunction } from "express";

interface TokenBucket {
  tokens: number;
  lastRefill: number;
}

const buckets = new Map<string, TokenBucket>();
const DEFAULT_LIMIT = 60;
const REFILL_INTERVAL = 60000; // 1 minute in milliseconds
const MAX_TOKENS = 60;

const getClientId = (req: Request): string => req.ip || "unknown";

const refillBucket = (bucket: TokenBucket): void => {
  const now = Date.now();
  const timePassed = now - bucket.lastRefill;
  const tokensToAdd = (timePassed / REFILL_INTERVAL) * DEFAULT_LIMIT;
  bucket.tokens = Math.min(MAX_TOKENS, bucket.tokens + tokensToAdd);
  bucket.lastRefill = now;
};

const cleanupBuckets = (): void => {
  const now = Date.now();
  const timeout = 10 * 60 * 1000; // 10 minutes
  for (const [key, bucket] of buckets.entries()) {
    if (now - bucket.lastRefill > timeout) {
      buckets.delete(key);
    }
  }
};

// Cleanup every 5 minutes
setInterval(cleanupBuckets, 5 * 60 * 1000);

export const clearBuckets = (): void => {
  buckets.clear();
};

export const rateLimiter = (req: Request, res: Response, next: NextFunction): void => {
  const clientId = getClientId(req);
  let bucket = buckets.get(clientId);

  if (!bucket) {
    bucket = { tokens: MAX_TOKENS, lastRefill: Date.now() };
    buckets.set(clientId, bucket);
  }

  refillBucket(bucket);

  const now = Date.now();
  const resetTime = Math.ceil((bucket.lastRefill + REFILL_INTERVAL - now) / 1000);

  if (bucket.tokens < 1) {
    res.status(429);
    res.set({
      "X-RateLimit-Limit": String(DEFAULT_LIMIT),
      "X-RateLimit-Remaining": String(Math.floor(bucket.tokens)),
      "X-RateLimit-Reset": String(Math.floor((bucket.lastRefill + REFILL_INTERVAL) / 1000)),
      "Retry-After": String(resetTime),
    });
    res.json({
      error: "Rate limit exceeded",
      retryAfter: resetTime,
    });
    return;
  }

  bucket.tokens -= 1;
  res.set({
    "X-RateLimit-Limit": String(DEFAULT_LIMIT),
    "X-RateLimit-Remaining": String(Math.floor(bucket.tokens)),
    "X-RateLimit-Reset": String(Math.floor((bucket.lastRefill + REFILL_INTERVAL) / 1000)),
  });

  next();
};

